package cn.iocoder.yudao.module.statistics.service.dashboard;
import cn.hutool.crypto.SecureUtil;import cn.iocoder.yudao.framework.common.pojo.PageResult;import cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder;import cn.iocoder.yudao.module.product.api.spu.ProductSpuApi;import cn.iocoder.yudao.module.product.api.spu.dto.ProductSpuRespDTO;import cn.iocoder.yudao.module.statistics.controller.admin.dashboard.vo.*;import cn.iocoder.yudao.module.statistics.dal.dataobject.dashboard.TrafficDailyDO;import cn.iocoder.yudao.module.statistics.dal.dataobject.product.ProductStatisticsDO;import cn.iocoder.yudao.module.statistics.dal.mysql.dashboard.TrafficDailyMapper;import cn.iocoder.yudao.module.statistics.dal.mysql.product.ProductStatisticsMapper;import org.springframework.stereotype.Service;import javax.annotation.Resource;import java.math.*;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;import java.util.stream.Collectors;
@Service public class DashboardQueryServiceImpl implements DashboardQueryService {
 @Resource private TrafficDailyMapper trafficMapper;@Resource private ProductStatisticsMapper productMapper;@Resource private ProductSpuApi productSpuApi;
 public DashboardSummaryRespVO summary(DashboardQueryReqVO q,boolean profit){Range r=range(q);DashboardSummaryRespVO current=summaryForRange(q,r,profit);if(Boolean.TRUE.equals(q.getCompare())){LocalDate today=LocalDate.now(ZoneId.of("Asia/Shanghai"));if(!r.end.isBefore(today))throw new IllegalArgumentException("comparison requires complete natural days and cannot include today");long days=ChronoUnit.DAYS.between(r.start,r.end)+1;LocalDate referenceEnd=r.start.minusDays(1),referenceStart=referenceEnd.minusDays(days-1);DashboardSummaryRespVO reference=summaryForRange(q,new Range(referenceStart,referenceEnd),profit);current.setReference(reference).setComparisonStartDate(referenceStart).setComparisonEndDate(referenceEnd).setChanges(changes(current,reference,profit));}current.setSnapshotId(snapshot(q,r,current));return current;}
 private DashboardSummaryRespVO summaryForRange(DashboardQueryReqVO q,Range r,boolean profit){if("SITE".equals(q.getScope()))return siteSummary(trafficMapper.selectBetween(r.start,r.end),profit);return productSummary(filtered(q,productMapper.selectBetween(r.start,r.end)),profit);}
 public List<DashboardTrendItemRespVO> trend(DashboardQueryReqVO q,boolean profit){Range r=range(q);List<DashboardTrendItemRespVO> current=trendForRange(q,r,profit);if(Boolean.TRUE.equals(q.getCompare())){Range referenceRange=referenceRange(r);Map<LocalDate,DashboardTrendItemRespVO> reference=trendForRange(q,referenceRange,profit).stream().collect(Collectors.toMap(DashboardTrendItemRespVO::getDay,item->item));for(DashboardTrendItemRespVO item:current){long offset=ChronoUnit.DAYS.between(r.start,item.getDay());LocalDate referenceDay=referenceRange.start.plusDays(offset);item.setReferenceDay(referenceDay).setReference(reference.get(referenceDay));}}return current;}
 private List<DashboardTrendItemRespVO> trendForRange(DashboardQueryReqVO q,Range r,boolean profit){if("SITE".equals(q.getScope()))return trafficMapper.selectBetween(r.start,r.end).stream().map(d->trend(d,profit)).sorted(Comparator.comparing(DashboardTrendItemRespVO::getDay)).collect(Collectors.toList());Map<LocalDate,List<ProductStatisticsDO>> grouped=filtered(q,productMapper.selectBetween(r.start,r.end)).stream().collect(Collectors.groupingBy(ProductStatisticsDO::getTime,TreeMap::new,Collectors.toList()));List<DashboardTrendItemRespVO> out=new ArrayList<>();for(Map.Entry<LocalDate,List<ProductStatisticsDO>> e:grouped.entrySet()){DashboardSummaryRespVO s=productSummary(e.getValue(),profit);DashboardTrendItemRespVO i=new DashboardTrendItemRespVO().setDay(e.getKey()).setProductDetailPv(s.getProductDetailPv()).setAddCartCount(s.getAddCartCount()).setPaidOrderCount(s.getPaidOrderCount()).setPaidRevenue(s.getPaidRevenue()).setRefundAmount(s.getRefundAmount()).setNetRevenue(s.getNetRevenue()).setTrafficDataStatus(s.getTrafficDataStatus());if(profit)i.setCostAmount(s.getCostAmount()).setGrossProfit(s.getGrossProfit()).setGrossMarginPercent(s.getGrossMarginPercent());out.add(i);}return out;}
 public List<DashboardProductRespVO> products(DashboardQueryReqVO q,boolean profit){return allProductRows(q,profit);}
 public PageResult<DashboardProductRespVO> productPage(DashboardQueryReqVO q,boolean profit){List<DashboardProductRespVO> rows=allProductRows(q,profit);if(rows.isEmpty())return PageResult.empty();int pageNo=q.getPageNo()==null?1:q.getPageNo(),pageSize=q.getPageSize()==null?100:q.getPageSize();if(pageNo<1||pageSize<1||pageSize>100)throw new IllegalArgumentException("page size must be between 1 and 100");long total=rows.size();int from=Math.min(rows.size(),(pageNo-1)*pageSize),to=Math.min(rows.size(),from+pageSize);return new PageResult<>(new ArrayList<>(rows.subList(from,to)),total);}
 private List<DashboardProductRespVO> allProductRows(DashboardQueryReqVO q,boolean profit){Range r=range(q);if("SITE".equals(q.getScope()))throw new IllegalArgumentException("product page requires PRODUCT scope");Comparator<DashboardProductRespVO> comparator=productComparator(q);List<DashboardProductRespVO> rows=aggregateProducts(filtered(q,productMapper.selectBetween(r.start,r.end))).stream().map(p->product(p,profit)).filter(row->matchesRisk(row,q.getRiskType(),profit)).collect(Collectors.toList());if(rows.isEmpty())return rows;Map<Long,ProductSpuRespDTO> products=productSpuApi.getSpuList(rows.stream().map(DashboardProductRespVO::getSpuId).collect(Collectors.toSet())).getCheckedData().stream().collect(Collectors.toMap(ProductSpuRespDTO::getId,p->p));if(q.getSpuId()!=null&&q.getCategoryId()!=null){ProductSpuRespDTO selected=products.get(q.getSpuId());if(selected==null||!q.getCategoryId().equals(selected.getCategoryId()))throw new IllegalArgumentException("selected SPU does not belong to the selected category");}rows=rows.stream().filter(row->{ProductSpuRespDTO spu=products.get(row.getSpuId());return q.getCategoryId()==null||(spu!=null&&q.getCategoryId().equals(spu.getCategoryId()));}).peek(row->enrich(row,products.get(row.getSpuId()))).collect(Collectors.toList());rows.sort(comparator);return rows;}
 private boolean matchesRisk(DashboardProductRespVO row,String risk,boolean profit){if(risk==null||risk.trim().isEmpty())return true;if("HIGH_TRAFFIC_LOW_CONVERSION".equals(risk))return "COMPLETE".equals(row.getTrafficDataStatus())&&nvl(row.getBrowseCount())>=100&&percent(nvl(row.getOrderCount()),nvl(row.getBrowseCount())).compareTo(new BigDecimal("1.00"))<0;if("HIGH_REFUND".equals(risk))return nvl(row.getOrderPayCount())>=10&&nvl(row.getOrderPayPrice())>=100000&&percent(nvl(row.getAfterSaleRefundPrice()),nvl(row.getOrderPayPrice())).compareTo(new BigDecimal("10.00"))>0;if("LOW_OR_NEGATIVE_MARGIN".equals(risk))return profit&&!"INCOMPLETE".equals(row.getProfitDataQuality())&&row.getGrossProfit()!=null&&(row.getGrossProfit()<0||(nvl(row.getOrderPayCount())>=5&&row.getGrossMarginPercent()!=null&&row.getGrossMarginPercent().compareTo(new BigDecimal("10.00"))<0));if("MISSING_COST".equals(risk))return profit&&nvl(row.getMissingCostItemCount())>0;throw new IllegalArgumentException("unsupported dashboard risk type");}
 private void enrich(DashboardProductRespVO row,ProductSpuRespDTO spu){if(spu!=null)row.setProductName(spu.getName()).setPicUrl(spu.getPicUrl()).setCategoryId(spu.getCategoryId());}
 public DashboardStageOverviewRespVO stageOverview(DashboardQueryReqVO q){Range r=range(q);DashboardStageOverviewRespVO result=new DashboardStageOverviewRespVO();if("SITE".equals(q.getScope())){DashboardSummaryRespVO s=siteSummary(trafficMapper.selectBetween(r.start,r.end),false);result.getItems().add(stage("HOME_UV",s.getHomeUv(),"users","visitor","APPLICABLE"));result.getItems().add(stage("PRODUCT_DETAIL_UV",s.getProductDetailUv(),"users","visitor","APPLICABLE"));result.getItems().add(stage("ADD_CART_USER",s.getAddCartUserCount(),"users","visitor","APPLICABLE"));result.getItems().add(stage("CHECKOUT_SESSION",s.getCheckoutStartCount(),"sessions","session","APPLICABLE"));result.getItems().add(stage("PAID_BUYER",s.getPaidBuyerCount(),"buyers","buyer","APPLICABLE"));}else{DashboardSummaryRespVO s=productSummary(filtered(q,productMapper.selectBetween(r.start,r.end)),false);result.getItems().add(stage("HOME_UV",null,"users","visitor","NOT_APPLICABLE"));result.getItems().add(stage("PRODUCT_DETAIL_UV",s.getProductDetailUv(),"users","visitor","APPLICABLE"));result.getItems().add(stage("ADD_CART_USER",s.getAddCartCount(),"events","event","APPLICABLE"));result.getItems().add(stage("CHECKOUT_SESSION",null,"sessions","session","NOT_APPLICABLE"));result.getItems().add(stage("PAID_BUYER",s.getPaidOrderCount(),"buyers","order","APPLICABLE"));}return result;}
 public DashboardAttentionRespVO attention(DashboardQueryReqVO q,boolean profit){Range r=range(q);DashboardAttentionRespVO out=new DashboardAttentionRespVO();for(ProductStatisticsDO p:aggregateProducts(filtered(q,productMapper.selectBetween(r.start,r.end)))){Long spu=p.getSpuId();if(!Integer.valueOf(1).equals(p.getTrafficDataStatus())){out.getNotEvaluated().add(skipped(spu,"HIGH_TRAFFIC_LOW_CONVERSION","TRAFFIC_INCOMPLETE","Traffic coverage is incomplete."));}else if(nvl(p.getBrowseCount())>=100&&percent(lng(p.getOrderCount()),lng(p.getBrowseCount())).compareTo(new BigDecimal("1.00"))<0){out.getItems().add(hit(spu,"HIGH_TRAFFIC_LOW_CONVERSION","High traffic with low browse-to-order conversion."));}if(nvl(p.getOrderPayCount())>=10&&nvl(p.getOrderPayPrice())>=100000&&percent(lng(p.getAfterSaleRefundPrice()),lng(p.getOrderPayPrice())).compareTo(new BigDecimal("10.00"))>0){out.getItems().add(hit(spu,"HIGH_REFUND","Refund percentage exceeds the configured rule."));}if(profit){if(Integer.valueOf(4).equals(p.getProfitDataQuality())){out.getNotEvaluated().add(skipped(spu,"LOW_OR_NEGATIVE_MARGIN","PROFIT_INCOMPLETE","Profit data is incomplete."));}else if(p.getGrossProfit()!=null&&(p.getGrossProfit()<0||(nvl(p.getOrderPayCount())>=5&&p.getGrossMarginPercent()!=null&&p.getGrossMarginPercent().compareTo(new BigDecimal("10.00"))<0))){out.getItems().add(hit(spu,"LOW_OR_NEGATIVE_MARGIN","Margin is negative or below the configured rule."));}if(nvl(p.getMissingCostItemCount())>0){out.getItems().add(hit(spu,"MISSING_COST","One or more cost movements are missing."));}}}return out;}
 private List<ProductStatisticsDO> filtered(DashboardQueryReqVO q,List<ProductStatisticsDO> rows){List<ProductStatisticsDO> selected=rows.stream().filter(p->q.getSpuId()==null||q.getSpuId().equals(p.getSpuId())).collect(Collectors.toList());if(q.getCategoryId()==null||selected.isEmpty())return selected;Map<Long,ProductSpuRespDTO> products=productSpuApi.getSpuList(selected.stream().map(ProductStatisticsDO::getSpuId).collect(Collectors.toSet())).getCheckedData().stream().collect(Collectors.toMap(ProductSpuRespDTO::getId,p->p));if(q.getSpuId()!=null){ProductSpuRespDTO spu=products.get(q.getSpuId());if(spu==null||!q.getCategoryId().equals(spu.getCategoryId()))throw new IllegalArgumentException("selected SPU does not belong to the selected category");}return selected.stream().filter(row->{ProductSpuRespDTO spu=products.get(row.getSpuId());return spu!=null&&q.getCategoryId().equals(spu.getCategoryId());}).collect(Collectors.toList());}
 private Comparator<DashboardProductRespVO> productComparator(DashboardQueryReqVO q){String field=q.getSortField()==null?"paidRevenue":q.getSortField();Map<String,java.util.function.Function<DashboardProductRespVO,? extends Comparable>> fields=new HashMap<>();fields.put("spuId",DashboardProductRespVO::getSpuId);fields.put("browseCount",DashboardProductRespVO::getBrowseCount);fields.put("orderCount",DashboardProductRespVO::getOrderCount);fields.put("paidRevenue",DashboardProductRespVO::getOrderPayPrice);fields.put("refundAmount",DashboardProductRespVO::getAfterSaleRefundPrice);fields.put("conversion",DashboardProductRespVO::getBrowseConvertPercent);fields.put("grossProfit",DashboardProductRespVO::getGrossProfit);fields.put("grossMargin",DashboardProductRespVO::getGrossMarginPercent);java.util.function.Function<DashboardProductRespVO,? extends Comparable> getter=fields.get(field);if(getter==null)throw new IllegalArgumentException("unsupported product sort field");Comparator<DashboardProductRespVO> comparator=Comparator.comparing(getter,Comparator.nullsLast(Comparator.naturalOrder()));if(!"asc".equalsIgnoreCase(q.getSortOrder()))comparator=comparator.reversed();return comparator.thenComparing(DashboardProductRespVO::getSpuId);}
 private List<ProductStatisticsDO> aggregateProducts(List<ProductStatisticsDO> rows){Map<Long,ProductStatisticsDO> grouped=new LinkedHashMap<>();for(ProductStatisticsDO row:rows){ProductStatisticsDO total=grouped.get(row.getSpuId());if(total==null){total=new ProductStatisticsDO().setSpuId(row.getSpuId()).setTrafficDataStatus(1).setProfitDataQuality(1);grouped.put(row.getSpuId(),total);}total.setBrowseCount(iadd(total.getBrowseCount(),row.getBrowseCount())).setBrowseUserCount(iadd(total.getBrowseUserCount(),row.getBrowseUserCount())).setCartCount(iadd(total.getCartCount(),row.getCartCount())).setOrderCount(iadd(total.getOrderCount(),row.getOrderCount())).setOrderPayCount(iadd(total.getOrderPayCount(),row.getOrderPayCount())).setOrderPayPrice(iadd(total.getOrderPayPrice(),row.getOrderPayPrice())).setAfterSaleCount(iadd(total.getAfterSaleCount(),row.getAfterSaleCount())).setAfterSaleRefundPrice(iadd(total.getAfterSaleRefundPrice(),row.getAfterSaleRefundPrice())).setKnownCostAmount(add(total.getKnownCostAmount(),row.getKnownCostAmount())).setGrossProfit(add(total.getGrossProfit(),row.getGrossProfit())).setExactCostItemCount(add(total.getExactCostItemCount(),row.getExactCostItemCount())).setEstimatedCostItemCount(add(total.getEstimatedCostItemCount(),row.getEstimatedCostItemCount())).setMissingCostItemCount(add(total.getMissingCostItemCount(),row.getMissingCostItemCount())).setTrafficDataStatus(statusCodeWorst(total.getTrafficDataStatus(),row.getTrafficDataStatus())).setProfitDataQuality(profitQualityWorst(total.getProfitDataQuality(),row.getProfitDataQuality()));}for(ProductStatisticsDO total:grouped.values()){BigDecimal conversion=percent(lng(total.getOrderCount()),lng(total.getBrowseCount()));total.setBrowseConvertPercent(conversion==null?null:conversion.intValue());if(nvl(total.getMissingCostItemCount())>0){total.setCostAmount(null).setGrossProfit(null).setGrossMarginPercent(null).setProfitDataQuality(4);}else{total.setCostAmount(total.getKnownCostAmount());Long net=nvl(total.getOrderPayPrice())-nvl(total.getAfterSaleRefundPrice());if(total.getKnownCostAmount()!=null)total.setGrossProfit(net-total.getKnownCostAmount());total.setGrossMarginPercent(total.getGrossProfit()==null||net<=0?null:percent(total.getGrossProfit(),net));}}return new ArrayList<>(grouped.values());}
 private Long iadd(Long a,Long b){if(a==null&&b==null)return null;return nvl(a)+nvl(b);}
 private Integer statusCodeWorst(Integer a,Integer b){return Math.max(a==null?3:a,b==null?3:b);}
 private Integer profitQualityWorst(Integer a,Integer b){return Math.max(a==null?5:a,b==null?5:b);}
 private DashboardStageOverviewRespVO.Item stage(String name,Long value,String unit,String dedupe,String applicability){return new DashboardStageOverviewRespVO.Item().setStage(name).setValue(value).setUnit(unit).setDedupeScope(dedupe).setApplicability(applicability);}
 private DashboardAttentionRespVO.Item hit(Long spu,String risk,String copy){return new DashboardAttentionRespVO.Item().setSpuId(spu).setRiskType(risk).setCopy(copy);}
 private DashboardAttentionRespVO.NotEvaluated skipped(Long spu,String risk,String reason,String copy){return new DashboardAttentionRespVO.NotEvaluated().setSpuId(spu).setRiskType(risk).setReasonCode(reason).setCopy(copy);}
 private DashboardSummaryRespVO siteSummary(List<TrafficDailyDO> list,boolean profit){DashboardSummaryRespVO s=new DashboardSummaryRespVO();for(TrafficDailyDO d:list){s.setHomePv(add(s.getHomePv(),d.getHomePv())).setHomeUv(add(s.getHomeUv(),d.getHomeUv())).setProductDetailPv(add(s.getProductDetailPv(),d.getProductDetailPv())).setProductDetailUv(add(s.getProductDetailUv(),d.getProductDetailUv())).setAddCartCount(add(s.getAddCartCount(),d.getAddCartCount())).setAddCartUserCount(add(s.getAddCartUserCount(),d.getAddCartUserCount())).setCheckoutStartCount(add(s.getCheckoutStartCount(),d.getCheckoutStartCount())).setPaidOrderCount(add(s.getPaidOrderCount(),d.getPaidOrderCount())).setPaidBuyerCount(add(s.getPaidBuyerCount(),d.getPaidBuyerCount())).setPaidItemCount(add(s.getPaidItemCount(),d.getPaidItemCount())).setPaidRevenue(add(s.getPaidRevenue(),d.getPaidRevenue())).setRefundAmount(add(s.getRefundAmount(),d.getRefundAmount()));if(d.getDay()!=null&&!Integer.valueOf(3).equals(d.getTrafficDataStatus()))s.setTrafficDataAvailableFrom(min(s.getTrafficDataAvailableFrom(),d.getDay()));metadata(s,d);if(profit)profit(s,d.getKnownCostAmount(),d.getCostAmount(),d.getGrossProfit(),d.getExactCostItemCount(),d.getEstimatedCostItemCount(),d.getMissingCostItemCount());}s.setNetRevenue(nvl(s.getPaidRevenue())-nvl(s.getRefundAmount()));finish(s,profit);return s;}
 private DashboardSummaryRespVO productSummary(List<ProductStatisticsDO> list,boolean profit){DashboardSummaryRespVO s=new DashboardSummaryRespVO();for(ProductStatisticsDO d:list){s.setProductDetailPv(add(s.getProductDetailPv(),lng(d.getBrowseCount()))).setProductDetailUv(add(s.getProductDetailUv(),lng(d.getBrowseUserCount()))).setAddCartCount(add(s.getAddCartCount(),lng(d.getCartCount()))).setPaidOrderCount(add(s.getPaidOrderCount(),lng(d.getOrderCount()))).setPaidItemCount(add(s.getPaidItemCount(),lng(d.getOrderPayCount()))).setPaidRevenue(add(s.getPaidRevenue(),lng(d.getOrderPayPrice()))).setRefundAmount(add(s.getRefundAmount(),lng(d.getAfterSaleRefundPrice())));if(d.getTime()!=null&&!Integer.valueOf(3).equals(d.getTrafficDataStatus()))s.setTrafficDataAvailableFrom(min(s.getTrafficDataAvailableFrom(),d.getTime()));if(profit)profit(s,d.getKnownCostAmount(),d.getCostAmount(),d.getGrossProfit(),d.getExactCostItemCount(),d.getEstimatedCostItemCount(),d.getMissingCostItemCount());s.setTrafficDataStatus(worst(s.getTrafficDataStatus(),status(d.getTrafficDataStatus())));s.setTrafficWatermark(min(s.getTrafficWatermark(),d.getTrafficWatermark())).setTradeWatermark(min(s.getTradeWatermark(),d.getTradeWatermark())).setRefundWatermark(min(s.getRefundWatermark(),d.getRefundWatermark()));}s.setNetRevenue(nvl(s.getPaidRevenue())-nvl(s.getRefundAmount()));finish(s,profit);return s;}
 private void finish(DashboardSummaryRespVO s,boolean profit){LocalDateTime asOf=min(min(s.getTrafficWatermark(),s.getTradeWatermark()),s.getRefundWatermark());s.setProfitVisible(profit).setAsOf(asOf);if(s.getTrafficDataStatus()==null)s.setTrafficDataStatus("UNAVAILABLE");if(!"COMPLETE".equals(s.getTrafficDataStatus()))s.setHomePv(null).setHomeUv(null).setProductDetailPv(null).setProductDetailUv(null);s.setBrowseOrderConversionPercent(percent(s.getPaidOrderCount(),s.getProductDetailPv())).setFreshnessStatus(freshness(asOf));if(profit){if(nvl(s.getMissingCostItemCount())>0){s.setCostAmount(null).setGrossProfit(null).setGrossMarginPercent(null);}else{s.setCostAmount(s.getKnownCostAmount()).setGrossProfit(s.getKnownCostAmount()==null?null:nvl(s.getNetRevenue())-s.getKnownCostAmount());s.setGrossMarginPercent(s.getGrossProfit()==null||nvl(s.getNetRevenue())<=0?null:percent(s.getGrossProfit(),s.getNetRevenue()));}}}
 private Map<String,DashboardMetricChangeRespVO> changes(DashboardSummaryRespVO current,DashboardSummaryRespVO reference,boolean profit){Map<String,DashboardMetricChangeRespVO> out=new LinkedHashMap<>();if("COMPLETE".equals(current.getTrafficDataStatus())&&"COMPLETE".equals(reference.getTrafficDataStatus())){out.put("homePv",countChange(current.getHomePv(),reference.getHomePv()));out.put("productDetailPv",countChange(current.getProductDetailPv(),reference.getProductDetailPv()));out.put("browseOrderConversionPercent",rateChange(current.getBrowseOrderConversionPercent(),reference.getBrowseOrderConversionPercent()));}out.put("paidOrderCount",countChange(current.getPaidOrderCount(),reference.getPaidOrderCount()));out.put("paidRevenue",countChange(current.getPaidRevenue(),reference.getPaidRevenue()));out.put("netRevenue",countChange(current.getNetRevenue(),reference.getNetRevenue()));if(profit)out.put("grossProfit",countChange(current.getGrossProfit(),reference.getGrossProfit()));return out;}
 private DashboardMetricChangeRespVO countChange(Long current,Long reference){DashboardMetricChangeRespVO change=new DashboardMetricChangeRespVO().setReferenceValue(reference);if(current==null||reference==null)return change;change.setChangeAmount(current-reference);if(reference!=0)change.setChangePercent(BigDecimal.valueOf(current-reference).multiply(BigDecimal.valueOf(100)).divide(BigDecimal.valueOf(reference),2,RoundingMode.HALF_UP));return change;}
 private DashboardMetricChangeRespVO rateChange(BigDecimal current,BigDecimal reference){DashboardMetricChangeRespVO change=new DashboardMetricChangeRespVO().setReferenceRate(reference);if(current!=null&&reference!=null)change.setChangePercentagePoints(current.subtract(reference).setScale(2,RoundingMode.HALF_UP));return change;}
 private String snapshot(DashboardQueryReqVO q,Range r,DashboardSummaryRespVO s){DashboardSummaryRespVO reference=s.getReference();String value=TenantContextHolder.getTenantId()+"|"+q.getScope()+"|"+r.start+"|"+r.end+"|"+q.getCategoryId()+"|"+q.getSpuId()+"|"+q.getRiskType()+"|"+Boolean.TRUE.equals(q.getCompare())+"|"+s.getTrafficWatermark()+"|"+s.getTradeWatermark()+"|"+s.getRefundWatermark()+"|"+s.getPaidRevenue()+"|"+s.getProductDetailPv()+"|"+(reference==null?"":reference.getTrafficWatermark()+"|"+reference.getTradeWatermark()+"|"+reference.getRefundWatermark()+"|"+reference.getPaidRevenue()+"|"+reference.getProductDetailPv());return SecureUtil.sha256(value);}
 private void profit(DashboardSummaryRespVO s,Long known,Long cost,Long gross,Long exact,Long estimated,Long missing){s.setKnownCostAmount(add(s.getKnownCostAmount(),known)).setExactCostItemCount(add(s.getExactCostItemCount(),exact)).setEstimatedCostItemCount(add(s.getEstimatedCostItemCount(),estimated)).setMissingCostItemCount(add(s.getMissingCostItemCount(),missing));}
 private void metadata(DashboardSummaryRespVO s,TrafficDailyDO d){s.setTrafficDataStatus(worst(s.getTrafficDataStatus(),status(d.getTrafficDataStatus())));s.setTrafficWatermark(min(s.getTrafficWatermark(),d.getTrafficWatermark())).setTradeWatermark(min(s.getTradeWatermark(),d.getTradeWatermark())).setRefundWatermark(min(s.getRefundWatermark(),d.getRefundWatermark()));}
 private DashboardTrendItemRespVO trend(TrafficDailyDO d,boolean profit){String trafficStatus=status(d.getTrafficDataStatus());DashboardTrendItemRespVO i=new DashboardTrendItemRespVO().setDay(d.getDay()).setHomePv("COMPLETE".equals(trafficStatus)?d.getHomePv():null).setProductDetailPv("COMPLETE".equals(trafficStatus)?d.getProductDetailPv():null).setAddCartCount(d.getAddCartCount()).setPaidOrderCount(d.getPaidOrderCount()).setPaidRevenue(d.getPaidRevenue()).setRefundAmount(d.getRefundAmount()).setNetRevenue(net(d.getPaidRevenue(),d.getRefundAmount())).setTrafficDataStatus(trafficStatus);if(profit)i.setCostAmount(d.getCostAmount()).setGrossProfit(d.getGrossProfit()).setGrossMarginPercent(d.getGrossMarginPercent());return i;}
 private DashboardProductRespVO product(ProductStatisticsDO p,boolean profit){DashboardProductRespVO v=new DashboardProductRespVO().setSpuId(p.getSpuId()).setBrowseCount(p.getBrowseCount()).setBrowseUserCount(p.getBrowseUserCount()).setCartCount(p.getCartCount()).setOrderCount(p.getOrderCount()).setOrderPayCount(p.getOrderPayCount()).setOrderPayPrice(p.getOrderPayPrice()).setAfterSaleCount(p.getAfterSaleCount()).setAfterSaleRefundPrice(p.getAfterSaleRefundPrice()).setBrowseConvertPercent(p.getBrowseConvertPercent()).setTrafficDataStatus(status(p.getTrafficDataStatus())).setProfitDataQuality(quality(p.getProfitDataQuality()));if(profit)v.setKnownCostAmount(p.getKnownCostAmount()).setCostAmount(p.getCostAmount()).setGrossProfit(p.getGrossProfit()).setGrossMarginPercent(p.getGrossMarginPercent()).setMissingCostItemCount(p.getMissingCostItemCount());return v;}
 private Range range(DashboardQueryReqVO q){if("SITE".equals(q.getScope())&&(q.getCategoryId()!=null||q.getSpuId()!=null))throw new IllegalArgumentException("SITE scope does not accept product filters");LocalDate end=q.getEndDate()==null?LocalDate.now().minusDays(1):q.getEndDate(),start=q.getStartDate()==null?end.minusDays(29):q.getStartDate();if(start.isAfter(end)||ChronoUnit.DAYS.between(start,end)>365)throw new IllegalArgumentException("date range must be 1 to 366 days");return new Range(start,end);}
 private Range referenceRange(Range current){LocalDate today=LocalDate.now(ZoneId.of("Asia/Shanghai"));if(!current.end.isBefore(today))throw new IllegalArgumentException("comparison requires complete natural days and cannot include today");long days=ChronoUnit.DAYS.between(current.start,current.end)+1;LocalDate end=current.start.minusDays(1);return new Range(end.minusDays(days-1),end);}
 private Long add(Long a,Long b){if(a==null&&b==null)return null;return nvl(a)+nvl(b);}private Long net(Long paid,Long refund){return paid==null&&refund==null?null:nvl(paid)-nvl(refund);}private Long lng(Number n){return n==null?null:n.longValue();}private long nvl(Number n){return n==null?0:n.longValue();}private BigDecimal percent(Long a,Long b){return a==null||b==null||b==0?null:BigDecimal.valueOf(a).multiply(BigDecimal.valueOf(100)).divide(BigDecimal.valueOf(b),2,RoundingMode.HALF_UP);}private String status(Integer v){return v==null||v==3?"UNAVAILABLE":v==2?"PARTIAL":"COMPLETE";}private String worst(String a,String b){if(a==null)return b;List<String> order=Arrays.asList("COMPLETE","PARTIAL","UNAVAILABLE");return order.indexOf(a)>=order.indexOf(b)?a:b;}private LocalDate min(LocalDate a,LocalDate b){return a==null?b:b==null?a:(a.isBefore(b)?a:b);}private LocalDateTime min(LocalDateTime a,LocalDateTime b){return a==null?b:b==null?a:(a.isBefore(b)?a:b);}private String freshness(LocalDateTime w){if(w==null)return"STALE";long sec=Duration.between(w,LocalDateTime.now()).getSeconds();return sec>1200?"STALE":sec>600?"DELAYED":"FRESH";}private String quality(Integer q){return q==null?"NOT_APPLICABLE":Arrays.asList("","EXACT","MIXED","ESTIMATED","INCOMPLETE","NOT_APPLICABLE").get(q);}private static class Range{final LocalDate start,end;Range(LocalDate s,LocalDate e){start=s;end=e;}}
}
